// WF2 runtime configuration. NON-SECRET values only.
const config = {
  emailUrl:       'https://postman-echo.com/post',      // stub SMTP / SendGrid sandbox
  failureDemoUrl: 'http://127.0.0.1:9/unreachable',     // refuses instantly, for demonstrating exhausted retries
  alertUrl:       'https://postman-echo.com/post',      // stub for the ops alert channel (Slack webhook / SendGrid)
  alertRecipient: 'ops-alerts@example.com',
  sheetId:        'YOUR_GOOGLE_SHEET_ID',
  deadLetterTab:  'Dead_Letter',
  maxAttempts:      4,   // 1 initial attempt plus 3 retries, as the specification specifies
  baseDelaySeconds: 1,   // exponential: 1s, 2s, 4s
  maxDelaySeconds:  8,
  demoMode: true
};
return $input.all().map(i => ({ json: { ...i.json, config }, binary: i.binary }));

// Same defensive gate as Workflow 1. Returns, never throws, so a bad payload cannot
// crash the run and the caller always gets a structured answer.
const item = $input.first();
const config = item.json.config;
const correlation_id = 'WF2-' + $execution.id;
const base = { config, correlation_id, received_at: new Date().toISOString() };

function fail(httpCode, status, message, extra) {
  return [{ json: { ...base, valid: false, httpCode, contractor_id: null,
    reason: status, last_error: message,
    response: Object.assign({ status, message, correlation_id }, extra || {}) } }];
}

let raw = null, parsed = null;
try {
  if (item.binary && item.binary.data && item.binary.data.data) {
    raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
  } else if (typeof item.json.body === 'string') {
    raw = item.json.body;
  }
  if (raw !== null) {
    if (raw.length > 16384) return fail(413, 'payload_too_large', 'Request body exceeds the 16 KiB limit.');
    parsed = JSON.parse(raw);
  } else {
    parsed = item.json.body;
  }
} catch (err) {
  return fail(400, 'invalid_json', 'Request body is not valid JSON. Nothing was processed.');
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  return fail(422, 'invalid_payload', 'Request body must be a JSON object.');
}

const REQUIRED = ['contractor_id','name','email','contract_type','start_date','agency_name'];
const CONTRACT_TYPES = ['PAYE','Umbrella','Ltd'];
const errors = [];
const c = {};

for (const f of REQUIRED) {
  let v = parsed[f];
  if (typeof v === 'number' && Number.isSafeInteger(v)) v = String(v);
  if (typeof v !== 'string' || v.trim() === '') { errors.push({ field: f, code: 'MISSING_OR_EMPTY' }); continue; }
  c[f] = v.trim();
}
if (c.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email)) errors.push({ field: 'email', code: 'INVALID_FORMAT' });
if (c.contract_type && !CONTRACT_TYPES.includes(c.contract_type)) {
  errors.push({ field: 'contract_type', code: 'INVALID_VALUE', allowed: CONTRACT_TYPES });
}

if (errors.length) {
  return [{ json: { ...base, valid: false, httpCode: 422,
    contractor_id: c.contractor_id || null, payload: c,
    reason: 'validation_failed',
    last_error: errors.length + ' field(s) failed validation',
    response: { status: 'validation_failed',
      message: errors.length + ' field(s) failed validation. No delivery was attempted.',
      correlation_id, errors } } }];
}

// Demo affordance, gated behind demoMode so it cannot fire in production: lets the
// retry / alert / dead-letter path be demonstrated without editing configuration.
const forceFailure = Boolean(config.demoMode && parsed._demo_force_failure === true);

return [{ json: { ...base, valid: true, payload: c, contractor_id: c.contractor_id, forceFailure } }];

const e = $input.first().json, p = e.payload, cfg = e.config;
const tag = cfg.demoMode ? '[DEMO] ' : '';

const body = [
  'Hello ' + p.name + ',',
  '',
  'Confirming your ' + p.contract_type + ' engagement with ' + p.agency_name +
    ', starting ' + p.start_date + '.',
  '',
  'Reference: ' + e.correlation_id
].join('\n');

return [{ json: { ...e,
  // Resolved once, here, so every retry hits the same target.
  targetUrl: e.forceFailure ? cfg.failureDemoUrl : cfg.emailUrl,
  emailBody: {
    personalizations: [{ to: [{ email: p.email, name: p.name }] }],
    subject: tag + 'Your ' + p.contract_type + ' engagement starts ' + p.start_date,
    content: [{ type: 'text/plain', value: body }]
  },
  retry: { attempt: 0, maxAttempts: cfg.maxAttempts, history: [],
           baseDelaySeconds: cfg.baseDelaySeconds, maxDelaySeconds: cfg.maxDelaySeconds }
} }];

// Classifies one attempt and decides whether another is warranted.
// This node is the retry mechanism. n8n's own retryOnFail setting is deliberately OFF
// on the HTTP node, because the specification requires the retry to live in workflow logic.
const base = $('Init Retry State').first().json;

// On the first pass the Wait node has not run. On later passes it carries the history.
let history = [];
try { history = $('Wait Before Retry').first().json.retry.history || []; } catch (err) { history = []; }

const r = $input.first().json;
const attempt = history.length + 1;
const status = Number(r.statusCode || 0);
const transport = Boolean(r.error) || !status;
const ok = !transport && status >= 200 && status < 300;

let errText = null;
if (!ok) {
  errText = transport
    ? String((r.error && (r.error.message || r.error.description)) || r.error || 'transport failure').slice(0, 200)
    : 'HTTP ' + status;
}

history = [...history, { attempt, at: new Date().toISOString(),
                         http_status: status || null, error: errText }];

// Retry only what is worth retrying. A 4xx other than 429 is a permanent client error:
// retrying a rejected recipient three times only delays the alert.
const retryable   = !ok && (transport || status >= 500 || status === 429);
const attemptsLeft = base.retry.maxAttempts - attempt;
const shouldRetry  = retryable && attemptsLeft > 0;

// Exponential backoff with jitter, so a provider recovering from an outage is not hit
// by every stalled execution at the same instant.
const raw    = base.retry.baseDelaySeconds * Math.pow(2, attempt - 1);
const capped = Math.min(raw, base.retry.maxDelaySeconds);
const delay  = Number((capped + capped * 0.25 * Math.random()).toFixed(1));

const outcome = ok ? 'delivered'
              : shouldRetry ? 'retrying'
              : retryable ? 'retries_exhausted'
              : 'permanent_failure';

return [{ json: { ...base, succeeded: ok, reason: ok ? null : outcome,
  last_error: errText, last_http_status: status || null,
  retry: { ...base.retry, attempt, history, shouldRetry, retryable,
           nextDelaySeconds: delay, outcome } } }];

const e = $input.first().json;
const attempts = e.retry.history.length;
return [{ json: { httpCode: 200, response: {
  status: 'delivered',
  message: attempts === 1
    ? 'Delivered on the first attempt.'
    : 'Delivered on attempt ' + attempts + ' of ' + e.retry.maxAttempts + '.',
  correlation_id: e.correlation_id,
  contractor_id: e.contractor_id,
  attempts,
  attempt_history: e.retry.history
} } }];

// Reached from two places: a payload that never passed validation, and a delivery that
// ran out of attempts (or failed permanently). Both are records that must not be lost.
const e = $input.first().json;
const cfg = e.config;
const hist = (e.retry && e.retry.history) || [];
const attempts = hist.length;

const reason = e.reason || 'unknown_failure';
const lastError = e.last_error || 'unknown';
const ts = new Date().toISOString();

// Allowlist, not denylist. Only failures <COMPANY> owns should page anyone. A malformed
// body, an invalid payload or a failed validation are all the CALLER's to fix, cannot be
// replayed, and are recorded without waking anyone up. Anything that reaches this list
// means our delivery pipeline failed.
const OPERATIONAL_FAILURES = ['retries_exhausted', 'permanent_failure'];
const alert_required = OPERATIONAL_FAILURES.includes(reason);
const caller_error = !alert_required;

return [{ json: {
  config: cfg,
  correlation_id: e.correlation_id,
  contractor_id: e.contractor_id || '',
  reason, attempts, lastError, ts, alert_required, caller_error,
  // Caller errors keep the status code the validator chose (400/413/422). Operational
  // failures are ours, so they are a 502.
  httpCode: caller_error ? (e.httpCode || 422) : 502,
  validationResponse: e.response || null,
  deadLetterRow: {
    correlation_id:   e.correlation_id,
    timestamp:        ts,
    contractor_id:    e.contractor_id || '',
    reason,
    attempts,
    last_error:       String(lastError).slice(0, 500),
    last_http_status: e.last_http_status || '',
    payload_json:     JSON.stringify(e.payload || {}).slice(0, 5000),
    alerted:          alert_required ? 'alert_required' : 'not_required'
  },
  alertBody: {
    to: cfg.alertRecipient,
    subject: '[ALERT] Notification delivery failed for ' + (e.contractor_id || 'unknown contractor'),
    contractor_id: e.contractor_id || '',
    correlation_id: e.correlation_id,
    error_message: String(lastError).slice(0, 500),
    timestamp: ts,
    attempts,
    attempt_history: hist,
    dead_letter_tab: cfg.deadLetterTab
  }
} }];

// Emits EXACTLY the nine dead-letter columns. n8n appends a new column for any field
// it cannot match to a header, so nothing else may travel with the item.
return [{ json: $input.first().json.deadLetterRow }];

// Reached from both outputs of the Sheets node, so a failed dead-letter write is
// recorded rather than lost. Context is restored from the last node that had it.
const e = $('Build Failure Record').first().json;
const r = $input.first().json;
return [{ json: { ...e, dead_letter_written: !r.error,
  dead_letter_error: r.error
    ? String((r.error && (r.error.message || r.error.description)) || r.error).slice(0, 300)
    : null } }];

const e = $('Capture Dead Letter Write').first().json;
const inp = $input.first().json;

// This node is reached either straight from 'Alert Required?' (no alert needed) or from
// BOTH outputs of the alert call. When an alert was required, the incoming item IS the
// alert response, so it is read directly rather than through a node reference.
let alert = { attempted: false, delivered: false, error: null };
if (e.alert_required) {
  const status = Number(inp.statusCode || 0);
  const transport = Boolean(inp.error) || !status;
  const ok = !transport && status >= 200 && status < 300;
  alert = {
    attempted: true,
    delivered: ok,
    error: ok ? null : (transport
      ? String((inp.error && (inp.error.message || inp.error.description)) || inp.error || 'transport failure').slice(0, 200)
      : 'HTTP ' + status)
  };
}

// A caller error keeps the body the validator already built and simply gains the
// persistence facts. It is not reframed as a delivery failure, because it wasn't one.
if (e.caller_error) {
  return [{ json: { httpCode: e.httpCode, response: { ...e.validationResponse,
    dead_letter_written: e.dead_letter_written,
    dead_letter_error: e.dead_letter_error } } }];
}

return [{ json: { httpCode: e.httpCode, response: {
  status: e.reason,
  message: e.reason === 'permanent_failure'
    ? 'The provider rejected this message permanently, so no further attempts were made. The record is in the dead letter.'
    : 'All ' + e.attempts + ' attempts failed. The record is in the dead letter and has not been lost.',
  correlation_id: e.correlation_id,
  contractor_id: e.contractor_id,
  attempts: e.attempts,
  last_error: e.lastError,
  dead_letter_written: e.dead_letter_written,
  dead_letter_error: e.dead_letter_error,
  alert
} } }];
